  "inlineSchema": "// Master DB — multi-tenant SaaS control plane\n//\n// این دیتابیس فقط کنترل SaaS رو نگه می‌داره:\n//  - استودیوها (tenant ها)\n//  - کاربران مرکزی (شماره موبایل + رمز)\n//  - عضویت کاربران در استودیوها\n//  - نشست‌ها (session)\n//  - کدهای OTP\n//  - تنظیمات پلتفرم (master Kavenegar API key, plans, و غیره)\n//  - اشتراک هر استودیو (plan, expiry, limits)\n//  - شارژ SMS هر استودیو + تراکنش‌ها\n//  - کاربران super-admin (فرزاد و هر کس دیگه‌ای که owner هست)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/master-client\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = \"file:../db/master.db\"\n}\n\n// ===================== STUDIOS (TENANTS) =====================\nmodel Studio {\n  id                String    @id @default(cuid())\n  name              String\n  nameEn            String?\n  dbName            String    @unique\n  isActive          Boolean   @default(true)\n  // اشتراک (subscription)\n  plan              String    @default(\"trial\") // \"trial\" | \"basic\" | \"pro\" | \"enterprise\" | \"suspended\"\n  subscriptionStart DateTime?\n  subscriptionEnd   DateTime?\n  // محدودیت‌های اشتراک (limits) — صفر یا منفی یعنی نامحدود\n  maxEmployees      Int       @default(5)\n  maxProjects       Int       @default(0) // 0 = unlimited\n  maxCustomers      Int       @default(0) // 0 = unlimited\n  maxStorageBytes   BigInt    @default(1073741824) // 1 GB default\n  // ذخیره‌سازی مصرف شده (cached total — refresh on upload/delete)\n  storageQuotaBytes BigInt    @default(1073741824)\n  storageUsedBytes  BigInt    @default(0)\n  // شماره موبایل استودیو (برای sender در Kavenegar)\n  studioPhone       String?\n  // اطلاعات تماس استودیو (برای پنل مدیریت)\n  ownerName         String?\n  ownerPhone        String?\n  city              String?\n  address           String?\n  notes             String?\n  // تنظیمات Kavenegar این استودیو (اگه child apikey داره)\n  kavenegarApikey   String? // child apikey (encrypted in production)\n  kavenegarSender   String? // شماره فرستنده اختصاصی\n  kavenegarLocalId  String? // شناسه داخلی در Kavenegar (معمولا = studio.id)\n  kavenegarStatus   String    @default(\"pending\") // \"pending\" | \"active\" | \"suspended\" | \"none\"\n  // شارژ SMS (به Rial)\n  smsCreditRial     Int       @default(0)\n  // تاریخ ایجاد و آپدیت\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  memberships     StudioMembership[]\n  smsTransactions SmsTransaction[]\n  subscriptions   SubscriptionEvent[]\n}\n\nmodel MasterUser {\n  id           String             @id @default(cuid())\n  phone        String             @unique\n  passwordHash String?\n  name         String\n  // super-admin flag — فقط فرزاد (و هر کس دیگه‌ای که owner پلتفرم باشه) true است\n  isSuperAdmin Boolean            @default(false)\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n  memberships  StudioMembership[]\n  sessions     Session[]\n}\n\nmodel StudioMembership {\n  id        String     @id @default(cuid())\n  userId    String\n  user      MasterUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n  studioId  String\n  studio    Studio     @relation(fields: [studioId], references: [id], onDelete: Cascade)\n  role      String // admin | manager | sales | photographer | videographer | pro_crew | editor | film_editor\n  isActive  Boolean    @default(true)\n  createdAt DateTime   @default(now())\n\n  @@unique([userId, studioId])\n}\n\nmodel OtpCode {\n  id        String   @id @default(cuid())\n  phone     String\n  code      String\n  hash      String\n  expiresAt DateTime\n  used      Boolean  @default(false)\n  attempts  Int      @default(0)\n  createdAt DateTime @default(now())\n\n  @@index([phone, createdAt])\n}\n\nmodel Session {\n  id        String     @id @default(cuid())\n  token     String     @unique\n  userId    String\n  user      MasterUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n  studioId  String?\n  role      String?\n  expiresAt DateTime\n  createdAt DateTime   @default(now())\n}\n\n// ===================== SMS TRANSACTIONS (شمارژ و مصرف SMS) =====================\nmodel SmsTransaction {\n  id                 String   @id @default(cuid())\n  studioId           String\n  studio             Studio   @relation(fields: [studioId], references: [id], onDelete: Cascade)\n  // نوع تراکنش: charge (افزایش شارژ) | send (مصرف برای ارسال) | refund (بازگشت) | adjustment (تنظیم دستی)\n  type               String // \"charge\" | \"send\" | \"refund\" | \"adjustment\"\n  // مبلغ به Rial (مثبت = افزایش شارژ، منفی = مصرف)\n  amountRial         Int\n  // برای تراکنش‌های ارسال: شماره گیرنده + متن پیام (کوتاه شده)\n  receptor           String?\n  messageSnippet     String? // 100 کاراکتر اول\n  // برای تراکنش‌های شارژ: توضیحات (مثلاً \"شارژ ماهانه آبان\")\n  description        String?\n  // شناسه پیام در Kavenegar (برای tracking)\n  kavenegarMessageId String?\n  // وضعیت: pending | sent | delivered | failed | refunded\n  status             String   @default(\"pending\")\n  // تاریخ\n  createdAt          DateTime @default(now())\n\n  @@index([studioId, createdAt])\n}\n\n// ===================== SUBSCRIPTION EVENTS (تاریخچه اشتراک) =====================\n// هر بار که اشتراک استودیو تغییر می‌کنه (upgrade/downgrade/renew/suspend)، یه رکورد اینجا ثبت می‌شه\nmodel SubscriptionEvent {\n  id              String    @id @default(cuid())\n  studioId        String\n  studio          Studio    @relation(fields: [studioId], references: [id], onDelete: Cascade)\n  // نوع رویداد: create | upgrade | downgrade | renew | suspend | reactivate | cancel\n  eventType       String\n  // plan قبلی و جدید\n  fromPlan        String?\n  toPlan          String\n  // مبلغ پرداختی (به Toman — برای گزارش‌های مالی)\n  amountPaidToman Int?\n  // مدت (روز)\n  durationDays    Int?\n  // تاریخ شروع و پایان اشتراک جدید\n  startAt         DateTime?\n  endAt           DateTime?\n  // توضیحات\n  note            String?\n  // تاریخ ثبت رویداد\n  createdAt       DateTime  @default(now())\n\n  @@index([studioId, createdAt])\n}\n\n// ===================== PLATFORM SETTINGS (تنظیمات پلتفرم) =====================\n// ذخیره تنظیمات سراسری پلتفرم (master Kavenegar API key, default plan, و غیره)\n// به صورت key-value (مثل SystemSetting در studio DB)\nmodel PlatformSetting {\n  key       String   @id\n  value     String   @default(\"\")\n  updatedAt DateTime @updatedAt\n}\n",
  "inlineSchemaHash": "61944f56c6c855a52e45684a7594d1518ff03813c033fc76ef2f4626ca1eee55",
